//! Lucide outline icons (paths copied from the design), registered as private-use glyphs
//! so they render crisply at any DPI, tint with the text color and sit inline in text.

macro_rules! icons {
    ($( $name:ident = $cp:literal, $w:literal, $path:literal; )*) => {
        $( #[allow(dead_code)] pub const $name: &str = $cp; )*
        const TABLE: &[(&str, f32, &str)] = &[ $( ($cp, $w, $path), )* ];
    };
}

