fn svg_for(path: &str, width: f32) -> String {
    if width == 0.0 {
        // Filled glyph (stop square).
        return format!(r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="{path}" fill="#ffffff"/></svg>"##);
    }
    format!(
        r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round"><path d="{path}"/></svg>"##
    )
}

/// Registers every icon as a glyph rasterizer. Safe to call more than once.
pub fn install(ctx: &egui::Context) {
    for (cp, width, path) in TABLE {
        let svg = svg_for(path, *width);
        match egui_extras::SvgGlyph::from_bytes(svg.as_bytes()) {
            Ok(g) => ctx.add_glyph_rasterizer(g.with_color(false).with_height(1.0).with_baseline_offset(-0.16).into_rasterizer(*cp)),
            Err(e) => eprintln!("kiln: icon {cp:?} failed to parse: {e}"),
        }
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_icon_parses() {
        for (cp, w, path) in super::TABLE {
            let svg = super::svg_for(path, *w);
            assert!(egui_extras::SvgGlyph::from_bytes(svg.as_bytes()).is_ok(), "icon {cp:?}");
        }
        let mut seen = std::collections::HashSet::new();
        assert!(super::TABLE.iter().all(|(cp, _, _)| seen.insert(*cp)), "duplicate code point");
    }
}
